  /* ---------- reports (Actions menu) ---------- */
  function reportData() { const s = stats(S.sel), P = s.P; const rows2 = s.ph.map(p => { const c = S.d.prc.filter(x => x.Project_Code === S.sel && x.Phase_Name === p.Phase_Name).reduce((a, x) => a + x.Amount, 0), m = S.d.prm.filter(x => x.Project_Code === S.sel && x.Phase_Name === p.Phase_Name), mc = m.reduce((a, x) => a + (x.Cost || x.People * x.Hours_Each * x.Rate), 0), h = m.reduce((a, x) => a + x.People * x.Hours_Each, 0); return [p.Phase_No, p.Phase_Name, p.Weight, p.Plan_Start, p.Plan_End, p.Actual_Start, p.Actual_End, Math.round(p.Progress * 10) / 10, p.Status, Math.round(c * 100) / 100, Math.round(mc * 100) / 100, Math.round(h * 10) / 10]; });
    const t = i => rows2.reduce((a, r) => a + (+r[i] || 0), 0); return { title: 'Project progress — ' + S.sel + ' ' + (P.Project_Name || ''), sheet: 'Project progress', note: `Overall ${fm(s.overall, 1)}% · budget ${fm(s.budget)} · actual ${fm(s.total)} · manager ${P.Project_Manager || '—'} · planned ${P.Start_Date || ''} → ${P.End_Date || ''}`, headers: ['#', 'Phase', 'Weight %', 'Plan start', 'Plan end', 'Actual start', 'Actual end', 'Progress %', 'Status', 'Costs', 'Manpower cost', 'Man-hours'], rows: rows2, totals: ['TOTAL', '', t(2), '', '', '', '', Math.round(s.overall * 10) / 10, '', Math.round(t(9) * 100) / 100, Math.round(t(10) * 100) / 100, Math.round(t(11) * 10) / 10] }; }
